public class SizeUtilsTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static Object sizeOrNull(Sized s) {
        return s == null ? null : s.size();
    }

    public static void main(String[] args) {
        check("ofFixed(5).size()", 5, sizeOrNull(SizeUtils.ofFixed(5)));
        check("ofFixed(0).size()", 0, sizeOrNull(SizeUtils.ofFixed(0)));
        check("ofFixed(-2).size()", -2, sizeOrNull(SizeUtils.ofFixed(-2)));

        Sized a = SizeUtils.ofFixed(3);
        Sized b = SizeUtils.ofFixed(9);
        Sized c = SizeUtils.ofFixed(4);

        check("largest of empty array", null, SizeUtils.largest(new Sized[0]));
        check("largest of single element", 7, sizeOrNull(SizeUtils.largest(new Sized[] { SizeUtils.ofFixed(7) })));
        check("largest of {3, 9, 4}", 9, sizeOrNull(SizeUtils.largest(new Sized[] { a, b, c })));
        check("largest when max is first", 9, sizeOrNull(SizeUtils.largest(new Sized[] { b, a, c })));
        check("largest with negatives", -1, sizeOrNull(SizeUtils.largest(new Sized[] { SizeUtils.ofFixed(-5), SizeUtils.ofFixed(-1) })));

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

