interface Sized {
    int size();
}

public class SizeUtils {

    public static Sized ofFixed(int n) {
        return () -> n;
    }

    public static Sized largest(Sized[] items) {
        if (items.length == 0) {
            return null;
        }
        Sized best = items[0];
        for (int i = 1; i < items.length; i++) {
            if (items[i].size() > best.size()) {
                best = items[i];
            }
        }
        return best;
    }
}
